BEGIN;
CREATE TABLE IF NOT EXISTS tenant.crm_mobile_devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,user_id uuid REFERENCES public.users(id) ON DELETE CASCADE,device_id text NOT NULL,platform text,app_version text,last_cursor bigint NOT NULL DEFAULT 0,last_sync_at timestamptz,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','revoked','inactive')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,device_id));
CREATE TABLE IF NOT EXISTS tenant.crm_mobile_mutations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,client_mutation_id text NOT NULL,device_id text,operation text NOT NULL,resource text NOT NULL,record_id uuid,idempotency_key text NOT NULL,payload jsonb NOT NULL,payload_hash text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','applied','conflict','failed','dead_letter')),result_payload jsonb,error_code text,error_message text,attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz,applied_at timestamptz,created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,updated_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,idempotency_key),UNIQUE(organization_id,client_mutation_id));
CREATE TABLE IF NOT EXISTS tenant.crm_mobile_change_log(sequence bigserial PRIMARY KEY,organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,resource text NOT NULL,record_id uuid NOT NULL,operation text NOT NULL,payload jsonb NOT NULL,payload_hash text NOT NULL,changed_by uuid REFERENCES public.users(id) ON DELETE SET NULL,changed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenant.crm_mobile_conflicts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,client_mutation_id text NOT NULL,resource text NOT NULL,record_id uuid,server_payload jsonb NOT NULL,client_payload jsonb NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','resolved','discarded')),resolution jsonb,resolved_by uuid REFERENCES public.users(id) ON DELETE SET NULL,resolved_at timestamptz,created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenant.crm_mobile_acceptance_evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,capability_id text NOT NULL,commit_sha text NOT NULL,status text NOT NULL CHECK(status IN('passed','failed','blocked')),evidence jsonb NOT NULL DEFAULT '{}'::jsonb,evidence_hash text NOT NULL,verified_by uuid REFERENCES public.users(id) ON DELETE SET NULL,verified_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,capability_id,commit_sha));
CREATE TABLE IF NOT EXISTS tenant.crm_final_acceptance_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,commit_sha text NOT NULL,status text NOT NULL CHECK(status IN('passed','failed','blocked')),capability_count integer NOT NULL,gate_results jsonb NOT NULL,evidence_hash text NOT NULL,verified_by uuid REFERENCES public.users(id) ON DELETE SET NULL,verified_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,commit_sha));
CREATE INDEX IF NOT EXISTS crm_mobile_change_cursor_idx ON tenant.crm_mobile_change_log(organization_id,sequence);CREATE INDEX IF NOT EXISTS crm_mobile_mutation_status_idx ON tenant.crm_mobile_mutations(organization_id,status,next_attempt_at,created_at);
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['crm_mobile_devices','crm_mobile_mutations','crm_mobile_change_log','crm_mobile_conflicts','crm_mobile_acceptance_evidence','crm_final_acceptance_runs'] LOOP EXECUTE format('ALTER TABLE tenant.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE tenant.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('DROP POLICY IF EXISTS tenant_organization_isolation ON tenant.%I',t);EXECUTE format('CREATE POLICY tenant_organization_isolation ON tenant.%I USING (organization_id=current_setting(''app.current_organization_id'',true)::uuid) WITH CHECK (organization_id=current_setting(''app.current_organization_id'',true)::uuid)',t);END LOOP;END$$;
CREATE OR REPLACE FUNCTION tenant.crm_mobile_evidence_immutable()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'CRM mobile acceptance evidence is immutable';END$$;DROP TRIGGER IF EXISTS crm_mobile_acceptance_immutable ON tenant.crm_mobile_acceptance_evidence;CREATE TRIGGER crm_mobile_acceptance_immutable BEFORE UPDATE OR DELETE ON tenant.crm_mobile_acceptance_evidence FOR EACH ROW EXECUTE FUNCTION tenant.crm_mobile_evidence_immutable();DROP TRIGGER IF EXISTS crm_final_acceptance_immutable ON tenant.crm_final_acceptance_runs;CREATE TRIGGER crm_final_acceptance_immutable BEFORE UPDATE OR DELETE ON tenant.crm_final_acceptance_runs FOR EACH ROW EXECUTE FUNCTION tenant.crm_mobile_evidence_immutable();GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA tenant TO vercent_app;GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA tenant TO vercent_app;COMMIT;
